1	export type CommandClass = 'test' | 'build' | 'typecheck' | 'lint' | 'other';
2	
3	const PM = '(?:npm|pnpm|yarn|bun)';
4	
5	const TEST_PATTERNS = [
6	  /\bvitest\b/,
7	  /\bjest\b/,
8	  /\bpytest\b/,
9	  /\bmocha\b/,
10	  /\bplaywright\s+test\b/,
11	  /\bgo\s+test\b/,
12	  /\bcargo\s+test\b/,
13	  /\bdotnet\s+test\b/,
14	  /\brspec\b/,
15	  /\bphpunit\b/,
16	  /\bpython\s+-m\s+unittest\b/,
17	  new RegExp(`\\b${PM}\\s+(?:run\\s+)?test\\b`),
18	  /\bmake\s+test\b/,
19	];
20	
21	const TYPECHECK_PATTERNS = [/\btsc\b/, /\bmypy\b/, /\bpyright\b/];
22	
23	const LINT_PATTERNS = [
24	  /\beslint\b/,
25	  /\bbiome\b/,
26	  /\bruff\b/,
27	  /\bflake8\b/,
28	  new RegExp(`\\b${PM}\\s+(?:run\\s+)?lint\\b`),
29	];
30	
31	const BUILD_PATTERNS = [
32	  new RegExp(`\\b${PM}\\s+(?:run\\s+)?build\\b`),
33	  /\bnext\s+build\b/,
34	  /\bvite\s+build\b/,
35	  /\bcargo\s+build\b/,
36	  /\bgo\s+build\b/,
37	  /\bmake\b/,
38	];
39	
40	const ORDER: [CommandClass, RegExp[]][] = [
41	  ['test', TEST_PATTERNS],
42	  ['typecheck', TYPECHECK_PATTERNS],
43	  ['lint', LINT_PATTERNS],
44	  ['build', BUILD_PATTERNS],
45	];
46	
47	function classifyPart(part: string): CommandClass {
48	  for (const [cls, patterns] of ORDER) {
49	    if (patterns.some((re) => re.test(part))) return cls;
50	  }
51	  return 'other';
52	}
53	
54	export function classifyCommand(command: string): CommandClass {
55	  const parts = command.split(/&&|\|\||[;|]/).map((p) => p.trim());
56	  const classes = new Set(parts.map(classifyPart));
57	  for (const [cls] of ORDER) {
58	    if (classes.has(cls)) return cls;
59	  }
60	  return 'other';
61	}
