6	const DEFAULT_MAX_BUFFER = 64 * 1024 * 1024;
7	
8	export async function git(repoDir: string, args: string[], opts?: { maxBuffer?: number }): Promise<string> {
9	  return new Promise((resolvePromise, reject) => {
10	    execFile(
11	      'git',
12	      args,
13	      { cwd: repoDir, maxBuffer: opts?.maxBuffer ?? DEFAULT_MAX_BUFFER },
14	      (err, stdout, stderr) => {
15	        if (err) reject(new Error(stderr?.toString() || err.message));
16	        else resolvePromise(stdout.toString());
17	      },
18	    );
19	  });
20	}
21	
22	function isRemoteUrl(repoUrlOrPath: string): boolean {
23	  return /^(https?:\/\/|git@|ssh:\/\/)/.test(repoUrlOrPath);
24	}
25	
26	function repoDirName(repoUrlOrPath: string): string {
27	  const cleaned = repoUrlOrPath.replace(/\.git$/, '');
28	  const parts = cleaned.split(/[/:]/).filter(Boolean);
29	  return parts.slice(-2).join('__');
30	}
31	
32	async function pathExists(path: string): Promise<boolean> {
33	  return access(path).then(() => true, () => false);
34	}
35	
36	/** Clones a URL under `<dataDir>/repos/<owner>__<name>` (or fetches if already cloned); a local path is used in place. */
37	export async function cloneOrUpdate(repoUrlOrPath: string, dataDir: string): Promise<string> {
38	  if (!isRemoteUrl(repoUrlOrPath)) return resolve(repoUrlOrPath);
39	
40	  const reposDir = resolve(dataDir, 'repos');
41	  await mkdir(reposDir, { recursive: true });
42	  const repoDir = resolve(reposDir, repoDirName(repoUrlOrPath));
43	
44	  if (await pathExists(repoDir)) {
45	    await git(repoDir, ['fetch', 'origin']).catch(() => undefined);
46	  } else {
47	    await new Promise<void>((resolvePromise, reject) => {
48	      execFile(
49	        'git',
50	        ['clone', '--filter=blob:limit=3m', repoUrlOrPath, repoDir],
51	        { cwd: reposDir, maxBuffer: DEFAULT_MAX_BUFFER },
52	        (err) => (err ? reject(err) : resolvePromise()),
53	      );
54	    });
55	  }
56	
57	  await git(repoDir, ['fetch', 'origin', '+refs/entire/*:refs/entire/*']).catch(() => undefined);
58	  await git(repoDir, ['fetch', 'origin', '+refs/heads/entire/*:refs/remotes/origin/entire/*']).catch(() => undefined);
59	
60	  return repoDir;
61	}
