63	const MAX_DIFF_FILES = 40;
64	const MAX_DIFF_COMMITS = 60;
65	const MAX_PATCH_CHARS = 6000;
66	// Larger than any realistic single secret match, so a secret sitting right at the truncation
67	// cut is still fully visible to redact() before that cut is made; bounds the pre-redaction
68	// window so redact() never scans an arbitrarily large patch from an untrusted clone.
69	const SAFETY_MARGIN = 8192;
70	const SHA_RE = /^[0-9a-f]{40}([0-9a-f]{24})?$/;
71	// Never run an external diff driver or textconv filter the cloned repo's own .gitattributes
72	// might name: those require a matching command defined in local/global git config to do
73	// anything, which an untrusted clone cannot supply on its own, but there is no reason to leave
74	// the door open.
75	const DIFF_SAFE_FLAGS = ['--no-textconv', '--no-ext-diff'];
76	
77	/** Splits one commit's `-p` patch body into redacted, length-capped text per changed file. */
78	function patchBodyToFileMap(body: string): Record<string, string> {
79	  const result: Record<string, string> = {};
80	  const chunks = body.split(/(?=^diff --git )/m).filter((c) => c.startsWith('diff --git'));
81	  for (const chunk of chunks.slice(0, MAX_DIFF_FILES)) {
82	    const headerMatch = /^diff --git a\/(.+?) b\/(.+?)$/m.exec(chunk);
83	    const path = headerMatch?.[2];
84	    if (!path) continue;
85	    const bounded = chunk.length <= MAX_PATCH_CHARS + SAFETY_MARGIN ? chunk : chunk.slice(0, MAX_PATCH_CHARS + SAFETY_MARGIN);
86	    result[path] = redactBounded(bounded).text.slice(0, MAX_PATCH_CHARS);
87	  }
88	  return result;
89	}
90	
91	/** Returns the redacted patch text for every file changed by `sha`, keyed by path, each capped at 6000 characters. */
92	export async function getDiff(repoDir: string, sha: string): Promise<Record<string, string>> {
93	  if (!SHA_RE.test(sha)) return {};
94	  let out: string;
95	  try {
96	    out = await git(repoDir, ['diff-tree', '-p', '--no-color', '--no-commit-id', '--root', ...DIFF_SAFE_FLAGS, sha]);
97	  } catch {
98	    return {};
99	  }
100	  return patchBodyToFileMap(out);
101	}
102	
103	/** Sorts shas by git's own commit-timestamp order (most recent first) with one lightweight, body-free call. */
104	async function sortByRecency(repoDir: string, shas: string[]): Promise<string[]> {
105	  let out: string;
106	  try {
107	    out = await git(repoDir, ['log', '--no-walk=sorted', '--format=%H', ...shas]);
108	  } catch {
109	    return shas;
110	  }
111	  return out.split('\n').map((s) => s.trim()).filter((s) => SHA_RE.test(s));
112	}
113	
114	/** The one-process-per-commit fallback `getDiffsBatched` uses when its batched parse looks untrustworthy. */
115	export async function getDiffsPerCommit(
116	  repoDir: string,
117	  shas: string[],
118	  maxCommits: number,
119	): Promise<{ diffs: Record<string, string>; droppedCount: number }> {
120	  const ordered = await sortByRecency(repoDir, shas);
121	  const kept = ordered.slice(0, maxCommits);
122	  const droppedCount = Math.max(0, ordered.length - maxCommits);
123	
124	  const diffs: Record<string, string> = {};
125	  for (const sha of kept) {
126	    for (const [path, patch] of Object.entries(await getDiff(repoDir, sha))) diffs[`${sha}:${path}`] = patch;
127	  }
128	  return { diffs, droppedCount };
129	}
130	
131	/**
132	 * True when every requested sha was parsed out of the batched `git log` output exactly once,
133	 * with nothing unexpected. A patch body that somehow contained the `\0` field separator (git's
134	 * own binary-content heuristic means this does not happen through ordinary diffed file content,
135	 * absent `-a`/`--text`/textconv, none of which this module uses) would desynchronize the
136	 * positional pairing below; this check exists so that, if it ever did, the result is a safe
137	 * fallback rather than silently mismatched or dropped diffs.
138	 */
139	function parsedCommitsAreTrustworthy(parsed: { sha: string }[], requested: string[]): boolean {
140	  if (parsed.length !== requested.length) return false;
141	  const requestedSet = new Set(requested);
142	  const seen = new Set<string>();
143	  for (const { sha } of parsed) {
144	    if (!requestedSet.has(sha) || seen.has(sha)) return false;
145	    seen.add(sha);
146	  }
147	  return true;
148	}
149	
150	/**
151	 * Returns the same per-file patches as calling `getDiff` for each sha, but with one `git log`
152	 * process for every commit instead of one per commit. Commits are kept in git's own most-recent-
153	 * first order and capped at 60; `droppedCount` reports how many older commits were left out.
154	 */
155	export async function getDiffsBatched(
156	  repoDir: string,
157	  shas: string[],
158	  maxCommits = MAX_DIFF_COMMITS,
159	): Promise<{ diffs: Record<string, string>; droppedCount: number }> {
160	  const validShas = Array.from(new Set(shas.filter((sha) => SHA_RE.test(sha))));
161	  if (validShas.length === 0) return { diffs: {}, droppedCount: 0 };
162	
163	  let out: string;
164	  try {
165	    out = await git(repoDir, ['log', '-p', '--no-color', '--no-walk=sorted', ...DIFF_SAFE_FLAGS, '--format=%x00%H%x00', ...validShas]);
166	  } catch {
167	    return getDiffsPerCommit(repoDir, validShas, maxCommits);
168	  }
169	
170	  const fields = out.split('\0');
171	  const commits: { sha: string; body: string }[] = [];
172	  for (let i = 1; i + 1 < fields.length; i += 2) {
173	    commits.push({ sha: fields[i]!.trim(), body: fields[i + 1]! });
174	  }
175	
176	  if (!parsedCommitsAreTrustworthy(commits, validShas)) return getDiffsPerCommit(repoDir, validShas, maxCommits);
177	
178	  const kept = commits.slice(0, maxCommits);
179	  const droppedCount = Math.max(0, commits.length - maxCommits);
180	
181	  const diffs: Record<string, string> = {};
182	  for (const { sha, body } of kept) {
183	    for (const [path, patch] of Object.entries(patchBodyToFileMap(body))) diffs[`${sha}:${path}`] = patch;
184	  }
185	  return { diffs, droppedCount };
186	}
