188	const MAX_FETCHED_BLOB_SIZE = 20 * 1024 * 1024;
189	const READ_TIMEOUT_MS = 30_000;
190	
191	/** Throws when an object's size (as git reports it) is over the limit, without reading its content. */
192	export async function assertBlobWithinFetchLimit(repoDir: string, oid: string, maxBytes = MAX_FETCHED_BLOB_SIZE): Promise<void> {
193	  const sizeOut = await git(repoDir, ['cat-file', '-s', oid]).catch(() => null);
194	  const size = sizeOut === null ? NaN : Number(sizeOut.trim());
195	  if (Number.isFinite(size) && size > maxBytes) {
196	    throw new Error(`object ${oid} is ${size} bytes, over the ${maxBytes}-byte fetch limit`);
197	  }
198	}
