200	interface PendingRead {
201	  resolve: (buf: Buffer | null) => void;
202	  reject: (err: Error) => void;
203	  timer: NodeJS.Timeout;
204	}
205	
206	/** An object whose body is being accumulated, within the size cap. */
207	interface InFlightBody {
208	  size: number;
209	  collected: Buffer[];
210	  have: number;
211	}
212	
213	/** A long-lived `git cat-file --batch` process: write an object id, read its full content back. */
214	export class ObjectBatchReader {
215	  private readonly proc: ChildProcessWithoutNullStreams;
216	  private readonly pending: PendingRead[] = [];
217	  private buffer: Buffer = Buffer.alloc(0);
218	  private closed = false;
219	  // Set once the reply stream can no longer be trusted to line up with pending requests at all
220	  // (a process exit or an unparseable header, as opposed to one oversized object, which is
221	  // handled per-request below); every read from this point on fails fast instead of risking a
222	  // later reply being resolved against the wrong pending request.
223	  private desynced = false;
224	  private readonly maxObjectSize: number;
225	  // Bytes still to be discarded from an oversized object's body, tracked by count rather than
226	  // buffered, so refusing one large object can never itself grow memory with its content.
227	  private skipRemaining = 0;
228	  private body: InFlightBody | null = null;
229	
230	  constructor(repoDir: string, maxObjectSize = MAX_FETCHED_BLOB_SIZE) {
231	    this.maxObjectSize = maxObjectSize;
232	    this.proc = spawn('git', ['cat-file', '--batch'], {
233	      cwd: repoDir,
234	      // Promisor objects outside a partial clone's filter would otherwise be fetched one at a
235	      // time, each a network round trip; this makes cat-file report them missing instead so the
236	      // caller can decide whether to fetch, in one explicit step.
237	      env: { ...process.env, GIT_NO_LAZY_FETCH: '1' },
238	    });
239	    this.proc.stdout.on('data', (chunk: Buffer) => {
240	      if (this.desynced) return; // the stream is torn down on poison(); nothing left to do with it
241	      this.buffer = this.buffer.length === 0 ? chunk : Buffer.concat([this.buffer, chunk]);
242	      this.drain();
243	    });
244	    const dead = (detail: string) => this.poison(new Error(`git cat-file --batch ${detail}`));
245	    this.proc.on('error', (err) => dead(`failed: ${err.message}`));
246	    this.proc.stdin.on('error', (err) => dead(`stdin failed: ${err.message}`));
247	    this.proc.on('exit', (code, signal) => {
248	      if (!this.closed) dead(`exited unexpectedly (code ${code}, signal ${signal})`);
249	    });
250	    this.proc.stdout.on('end', () => {
251	      if (!this.closed) dead('closed its output unexpectedly');
252	    });
253	  }
254	
255	  /** Tears the reader down entirely: every *other* pending request fails too, since the reply stream can no longer be trusted to line up with them. */
256	  private poison(err: Error): void {
257	    if (this.desynced) return;
258	    this.desynced = true;
259	    this.buffer = Buffer.alloc(0);
260	    this.body = null;
261	    this.skipRemaining = 0;
262	    this.proc.stdout.removeAllListeners('data');
263	    if (!this.closed) {
264	      this.closed = true;
265	      this.proc.stdin.end();
266	      this.proc.kill();
267	    }
268	    while (this.pending.length > 0) {
269	      const next = this.pending.shift()!;
270	      clearTimeout(next.timer);
271	      next.reject(err);
272	    }
273	  }
274	
275	  private drain(): void {
276	    while (true) {
277	      if (this.skipRemaining > 0) {
278	        const take = Math.min(this.skipRemaining, this.buffer.length);
279	        this.buffer = this.buffer.subarray(take);
280	        this.skipRemaining -= take;
281	        if (this.skipRemaining > 0) return;
282	        continue;
283	      }
284	
285	      if (this.body) {
286	        const need = this.body.size + 1 - this.body.have; // +1 for the trailing newline after content
287	        const take = Math.min(need, this.buffer.length);
288	        if (take > 0) {
289	          this.body.collected.push(Buffer.from(this.buffer.subarray(0, take)));
290	          this.body.have += take;
291	          this.buffer = this.buffer.subarray(take);
292	        }
293	        if (this.body.have < this.body.size + 1) return;
294	        const data = Buffer.concat(this.body.collected).subarray(0, this.body.size);
295	        this.body = null;
296	        const next = this.pending.shift()!;
297	        clearTimeout(next.timer);
298	        next.resolve(data);
299	        continue;
300	      }
301	
302	      if (this.pending.length === 0) return;
303	      const nl = this.buffer.indexOf(0x0a);
304	      if (nl === -1) return;
305	      const header = this.buffer.subarray(0, nl).toString('utf8');
306	      this.buffer = this.buffer.subarray(nl + 1);
307	
308	      if (header.endsWith(' missing')) {
309	        const next = this.pending.shift()!;
310	        clearTimeout(next.timer);
311	        next.resolve(null);
312	        continue;
313	      }
314	      const m = /^[0-9a-f]{40,64} \S+ (\d+)$/.exec(header);
315	      if (!m) {
316	        // The reply no longer lines up with what cat-file's protocol promises; trust nothing
317	        // further rather than guessing where the next real header starts.
318	        this.poison(new Error(`git cat-file --batch sent an unparseable reply header: ${JSON.stringify(header)}`));
319	        return;
320	      }
321	      const size = Number(m[1]);
322	      if (size > this.maxObjectSize) {
323	        // Fail only this one request and discard its body by count, without buffering it: a
324	        // single oversized object must not take the whole reader (and every other session still
325	        // being read through it) down with it.
326	        const next = this.pending.shift()!;
327	        clearTimeout(next.timer);
328	        next.reject(new Error(`git cat-file --batch reported an object of ${size} bytes, over the ${this.maxObjectSize}-byte read limit`));
329	        this.skipRemaining = size + 1;
330	        continue;
331	      }
332	      this.body = { size, collected: [], have: 0 };
333	    }
334	  }
335	
336	  /** Resolves with the object's content, or `null` when the object is missing locally. */
337	  read(oid: string): Promise<Buffer | null> {
338	    // desynced is checked first: poison() also sets closed (so it can reuse the same teardown as
339	    // an explicit close()), but a poisoned reader must reject, never resolve `null` as if the
340	    // object were merely missing — a caller like readBlobOrFetch would otherwise read that as
341	    // "missing, fetch it" and paper over the real failure with a wasted fetch and a misleading
342	    // error.
343	    if (this.desynced) return Promise.reject(new Error('git cat-file --batch reader is desynchronized and no longer usable'));
344	    if (this.closed) return Promise.resolve(null);
345	    return new Promise((resolvePromise, reject) => {
346	      const timer = setTimeout(() => {
347	        const idx = this.pending.findIndex((p) => p.resolve === resolvePromise);
348	        if (idx !== -1) this.pending.splice(idx, 1);
349	        this.poison(new Error(`git cat-file --batch read of ${oid} timed out after ${READ_TIMEOUT_MS}ms`));
350	      }, READ_TIMEOUT_MS);
351	      this.pending.push({ resolve: resolvePromise, reject, timer });
352	      this.proc.stdin.write(`${oid}\n`);
353	    });
354	  }
355	
356	  close(): void {
357	    if (this.closed) return;
358	    this.closed = true;
359	    for (const p of this.pending) clearTimeout(p.timer);
360	    this.proc.stdin.end();
361	    this.proc.kill();
362	  }
363	}
364	
365	/**
366	 * Reads a blob through the batch reader; a blob missing locally (beyond the clone filter) is
367	 * fetched once and retried, after checking its size stays within `assertBlobWithinFetchLimit` —
368	 * the content is untrusted, so an unbounded fetch-and-buffer here would let a single oversized
369	 * blob exhaust memory or bandwidth.
370	 */
371	export async function readBlobOrFetch(repoDir: string, reader: ObjectBatchReader, oid: string): Promise<Buffer> {
372	  const first = await reader.read(oid);
373	  if (first !== null) return first;
374	  await git(repoDir, ['fetch', 'origin', oid]);
375	  await assertBlobWithinFetchLimit(repoDir, oid);
376	  const second = await reader.read(oid);
377	  if (second === null) throw new Error(`object ${oid} is unavailable even after fetching it`);
378	  return second;
379	}
