1	import { git } from './git';
2	
3	const TRAILER_RE = /^Entire-Checkpoint:\s*(\S+)\s*$/m;
4	const SHA_RE = /^[0-9a-f]{40}([0-9a-f]{24})?$/;
5	
6	function extractCheckpointId(message: string): string | null {
7	  const m = TRAILER_RE.exec(message);
8	  return m ? m[1]! : null;
9	}
10	
11	// NUL cannot appear inside a git commit's sha or message, so it is a collision-proof field and
12	// record separator against commit bodies from an untrusted, cloned public repository.
13	/** Maps checkpoint id -> commit SHAs by scanning commit bodies for an `Entire-Checkpoint:` trailer. */
14	export async function mapCheckpointCommits(repoDir: string): Promise<Map<string, string[]>> {
15	  const map = new Map<string, string[]>();
16	
17	  let out: string;
18	  try {
19	    out = await git(repoDir, ['log', '-z', '--exclude=refs/heads/entire/*', '--branches', '--tags', '--format=%H%x00%B']);
20	  } catch {
21	    return map;
22	  }
23	
24	  const fields = out.split('\0');
25	  for (let i = 0; i + 1 < fields.length; i += 2) {
26	    const sha = fields[i]!.replace(/^\n+/, '').trim();
27	    const body = fields[i + 1]!;
28	    if (!SHA_RE.test(sha)) continue;
29	    const id = extractCheckpointId(body);
30	    if (!id) continue;
31	    const list = map.get(id) ?? [];
32	    list.push(sha);
33	    map.set(id, list);
34	  }
35	
36	  return map;
37	}
