2	import { copyFileSync, existsSync, mkdirSync, readFileSync } from 'node:fs';
3	import { dirname, join } from 'node:path';
4	import type { LineTiming } from '@dailies/core';
5	import { TtsQuotaError, type TtsProvider } from './gemini';
6	import { writeWav } from './wav';
7	import { detectSilences } from './silence';
8	import { alignLines, estimateTimings } from './align';
9	
10	export * from './gemini';
11	export * from './wav';
