1	import { resolve } from 'node:path';
2	import { z } from 'zod';
3	import { defineTool, runAgent, type Tool } from '@dailies/agent';
4	import { Beat, type Entry, type IngestArtifact, type Session } from '@dailies/core';
5	import { editorPrompt } from '../prompts/editor';
6	import type { Stage } from '../types';
7	import type { StageDeps } from './index';
