1	import type { Session, Facts } from './schema';
2	export function computeFacts(sessions: Session[]): Facts {
3	  const commits = new Set(sessions.flatMap((s) => s.commits));
4	  const files = new Set(sessions.flatMap((s) => s.filesTouched));
5	  const calls = sessions.reduce((n, s) => n + s.entries.filter((e) => e.kind === 'tool_call').length, 0);
6	  const minutes = sessions.reduce((n, s) => n + (s.endedAt ? (Date.parse(s.endedAt) - Date.parse(s.startedAt)) / 60000 : 0), 0);
7	  return {
8	    'sessions.count': sessions.length,
9	    'commits.count': commits.size,
10	    'files.count': files.size,
11	    'turns.total': sessions.reduce((n, s) => n + s.turnCount, 0),
12	    'tools.calls': calls,
13	    'tokens.output': sessions.reduce((n, s) => n + s.tokens.output, 0),
14	    'duration.minutes': Math.round(minutes),
15	  };
16	}
